def touches_different(g,bg):
    # color with cells orthogonally adjacent to a different non-bg color
    H,W=len(g),len(g[0])
    cells=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg: cells[g[i][j]].append((i,j))
    out=[]
    for c,vv in cells.items():
        for y,x in vv:
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                if 0<=y+dy<H and 0<=x+dx<W:
                    c2=g[y+dy][x+dx]
                    if c2!=bg and c2!=c: out.append((c,c2))
    return sorted(set(out))
